async function openAppointments(){if(!current)return authModal('login');try{const {appointments}=await api('/api/appointments');modal.innerHTML=`<div class="modal-head"><h2>حجوزاتي</h2><button class="close" data-close>×</button></div><button class="text-link" id="openServiceRequests">طلبات الخدمات الأخرى ←</button>${appointments.map(a=>`<article class="booking-doctor" style="display:block"><b>${escapeHtml(a.doctor)} — ${escapeHtml(a.specialty)}</b><small>${escapeHtml(a.branch)} • ${escapeHtml(a.address)}<br>${escapeHtml(a.startsAt)} • ${escapeHtml(a.status)}</small>${a.status==='booked'?`<button class="text-link" data-cancel="${escapeHtml(a.id)}">إلغاء الحجز</button>`:''}</article>`).join('')||'<p>لا توجد حجوزات عيادات.</p>'}`;modalBack.classList.add('open');$('[data-close]').onclick=closeModal;$('#openServiceRequests').onclick=openMyRequests;document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{try{await api(`/api/appointments/${b.dataset.cancel}/cancel`,{method:'POST',body:'{}'});toast('تم إلغاء الحجز.');openAppointments();}catch(e){toast(e.message);}});}catch(e){toast(e.message);}}
const serviceNames={hospital:'حجز مستشفى',home_visit:'زيارة منزلية',phone_consult:'استشارة هاتفية',video_consult:'استشارة فيديو',medicine_delivery:'طلب أدوية',lab_booking:'حجز تحليل',imaging_booking:'حجز أشعة'};
const serviceStatuses={pending_provider_confirmation:'بانتظار تأكيد مقدم الخدمة',accepted:'تم قبول الطلب',rejected:'تعذر توفير الخدمة',completed:'مكتمل',cancelled:'ملغي'};
function openServiceRequest(type){if(!current){pendingServiceRequest=type;authModal('login');return;}if(current.role!=='patient'){toast('إرسال الطلبات متاح لحساب المريض.');return;}const name=serviceNames[type];if(!name)return;const specialtyOptions=CLINIC_DATA.specialties.map(([,s])=>`<option>${escapeHtml(s)}</option>`).join('');const isMedicine=type==='medicine_delivery',isTest=['lab_booking','imaging_booking'].includes(type),isTele=['phone_consult','video_consult'].includes(type);let fields='';if(isMedicine){fields=`<div class="form-row"><label>أسماء الأدوية المطلوبة</label><textarea name="medicines" required minlength="2" maxlength="3000" rows="3" style="width:100%;padding:11px;border:1px solid #dae5e6;border-radius:10px"></textarea><small>الصيدلي يؤكد التوفر والوصفة قبل تجهيز الطلب.</small></div><div class="form-row"><label>رقم الهاتف</label><input name="phone" required placeholder="01xxxxxxxxx"></div><div class="form-row"><label>المنطقة</label><input name="area" required></div><div class="form-row"><label>عنوان التوصيل</label><input name="address" required minlength="8"></div>`;}else if(isTest){fields=`<div class="form-row"><label>${type==='lab_booking'?'اسم التحليل':'نوع الأشعة'}</label><input name="serviceName" required minlength="2" placeholder="اكتب الفحص المطلوب"></div><div class="form-row"><label>المنطقة أو الفرع المفضل</label><input name="area" required></div><div class="form-row"><label>التاريخ المفضل</label><input name="preferredDate" type="date" min="${new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo'}).format(new Date())}"></div><div class="form-row"><label>ملاحظة (اختياري)</label><input name="notes" maxlength="1200"></div>`;}else{fields=`<div class="form-row"><label>التخصص المطلوب</label><select name="specialty" required>${specialtyOptions}</select></div><div class="form-row"><label>المنطقة</label><input name="area" required></div>${type==='home_visit'?'<div class="form-row"><label>العنوان بالتفصيل</label><input name="address" required minlength="8"></div>':''}${isTele?'<div class="form-row"><label>رقم الهاتف</label><input name="phone" required placeholder="01xxxxxxxxx"></div>':''}<div class="form-row"><label>التاريخ المفضل (اختياري)</label><input name="preferredDate" type="date"></div><div class="form-row"><label>ملاحظات (اختياري)</label><textarea name="notes" maxlength="1200" rows="2" style="width:100%;padding:11px;border:1px solid #dae5e6;border-radius:10px"></textarea></div>`;}modal.innerHTML=`<div class="modal-head"><h2>${name}</h2><button class="close" data-close>×</button></div><p style="color:#71838b;font-size:13px;line-height:1.8">أرسل طلبك مجانًا. الطلب لا يُعد حجزًا مؤكدًا؛ ستظهر حالته هنا بعد مراجعة التوفر والتواصل معك.</p><form id="serviceRequestForm">${fields}<p id="serviceRequestError" style="color:#ad4848"></p><button class="btn" style="width:100%">إرسال الطلب</button></form>`;modalBack.classList.add('open');$('[data-close]').onclick=closeModal;$('#serviceRequestForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(e.currentTarget).entries());data.serviceType=type;try{const result=await api('/api/service-requests',{method:'POST',body:JSON.stringify(data)});modal.innerHTML=`<div class="success"><div>✓</div><h2>تم استلام طلبك</h2><p>رقم الطلب: ${escapeHtml(result.request.id)}<br>الحالة: بانتظار تأكيد مقدم الخدمة.<br>لا تعتبر الخدمة مؤكدة حتى يتواصل معك الفريق.</p><button class="btn" id="viewRequests">متابعة طلباتي</button></div>`;$('#viewRequests').onclick=openMyRequests;}catch(err){$('#serviceRequestError').textContent=err.message;button.disabled=false;}};}
async function openMyRequests(){if(!current)return authModal('login');try{const {requests}=await api('/api/service-requests');modal.innerHTML=`<div class="modal-head"><h2>طلبات الخدمات</h2><button class="close" data-close>×</button></div>${requests.map(r=>`<article class="booking-doctor" style="display:block"><b>${escapeHtml(serviceNames[r.serviceType]||'طلب خدمة')}</b><small>${escapeHtml(serviceStatuses[r.status]||r.status)} • ${new Date(r.createdAt).toLocaleString('ar-EG')}${r.details.serviceName?`<br>${escapeHtml(r.details.serviceName)}`:''}${r.details.specialty?`<br>${escapeHtml(r.details.specialty)}`:''}${r.details.area?` • ${escapeHtml(r.details.area)}`:''}${r.adminNote?`<br>ملاحظة المركز: ${escapeHtml(r.adminNote)}`:''}</small>${r.status==='pending_provider_confirmation'?`<button class="text-link" data-cancel-request="${escapeHtml(r.id)}">إلغاء الطلب</button>`:''}</article>`).join('')||'<p>لا توجد طلبات خدمات بعد.</p>'}`;modalBack.classList.add('open');$('[data-close]').onclick=closeModal;document.querySelectorAll('[data-cancel-request]').forEach(b=>b.onclick=async()=>{try{await api(`/api/service-requests/${b.dataset.cancelRequest}/cancel`,{method:'POST',body:'{}'});toast('تم إلغاء الطلب.');openMyRequests();}catch(e){toast(e.message);}});}catch(e){toast(e.message);}}
async function openBooking(doctor){if(current&&current.role!=='patient'){toast('الحجز متاح بحساب المريض.');return;}if(!current){pendingBookingDoctor=doctor;return authModal('login');}const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());modal.innerHTML=`<div class="modal-head"><h2>حجز موعد</h2><button class="close" data-close>×</button></div><article class="booking-doctor"><b>${escapeHtml(doctor.name)} — ${escapeHtml(doctor.specialty)}</b><small>${escapeHtml(doctor.branch)} • ${doctor.consultationFee} جنيه للكشف</small></article><div class="form-row"><label>تاريخ الزيارة</label><input id="bookingDate" type="date" value="${today}" min="${today}"></div><div id="slotList" class="slots">جارٍ تحميل المواعيد…</div><p id="bookingError" style="color:#ad4848"></p><button class="btn" id="confirmBooking" style="width:100%" disabled>تأكيد الحجز</button>`;modalBack.classList.add('open');$('[data-close]').onclick=closeModal;const loadSlots=async()=>{const date=$('#bookingDate').value;try{const {slots}=await api(`/api/public/slots?doctorId=${encodeURIComponent(doctor.id)}&date=${encodeURIComponent(date)}`);$('#slotList').innerHTML=slots.length?slots.map(t=>`<button class="slot" data-slot="${t}">${t}</button>`).join(''):'<small>لا توجد مواعيد متاحة في هذا اليوم.</small>';document.querySelectorAll('[data-slot]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-slot]').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');$('#confirmBooking').disabled=false;});}catch(e){$('#slotList').textContent=e.message;}};$('#bookingDate').onchange=loadSlots;$('#confirmBooking').onclick=async()=>{const selected=$('.slot.selected');if(!selected)return;try{await api('/api/appointments',{method:'POST',body:JSON.stringify({doctorId:doctor.id,startsAt:$('#bookingDate').value+'T'+selected.dataset.slot})});toast('تم حجز الموعد.');closeModal();openAppointments();}catch(e){$('#bookingError').textContent=e.message;await loadSlots();}};await loadSlots();}
const recordLabels={lab:'نتيجة تحليل',imaging:'تقرير أشعة',visit:'زيارة',diagnosis:'تشخيص',treatment:'علاج',medication:'دواء',surgery:'عملية/إجراء',allergy:'حساسية',appointment:'حجز كشف',follow_up:'موعد إعادة'};
function recordCard(r){const status=r.category==='appointment'||r.category==='follow_up'?`حالة الموعد: ${escapeHtml(({booked:'محجوز',confirmed:'مؤكد',in_progress:'قيد الكشف',completed:'مكتمل',cancelled:'ملغي'})[r.status]||r.status||'—')}`:r.status==='clinician_verified'?`موثق سريريًا بواسطة ${escapeHtml(r.doctorName||'مقدم الرعاية')}`:r.status==='uploaded_pending_clinician_review'?'مرفوع، بانتظار مراجعة مقدم الرعاية':r.status==='staff_entered_pending_clinician_review'||r.status==='staff_updated_pending_clinician_review'?'أضافه فريق المركز، بانتظار مراجعة الطبيب':'موثق في الملف';return `<article class="booking-doctor" style="display:block"><b>${escapeHtml(recordLabels[r.category]||'سجل طبي')} — ${escapeHtml(r.title)}</b><small>${r.serviceDate?escapeHtml(r.serviceDate)+' • ':''}${r.fileName?escapeHtml(r.fileName)+' • ':''}${new Date(r.createdAt||r.startsAt).toLocaleString('ar-EG')}<br>${escapeHtml(status)}${r.detail?`<br>${escapeHtml(r.detail)}`:''}</small>${r.fileName?`<button class="text-link" data-download="${escapeHtml(r.id)}">تنزيل التقرير</button>`:''}</article>`;}
async function openMedicalRecord(){if(!current)return authModal('login');if(current.role!=='patient'){toast('الملف الطبي متاح لحساب المريض.');return;}modal.innerHTML='<div class="modal-head"><h2>الملف الطبي</h2><button class="close" data-close>×</button></div><p>جارٍ تحميل ملفك…</p>';modalBack.classList.add('open');$('[data-close]').onclick=closeModal;try{const record=await api('/api/medical-record');renderMedicalRecord(record);}catch(e){modal.innerHTML=`<div class="modal-head"><h2>الملف الطبي</h2><button class="close" data-close>×</button></div><p>${escapeHtml(e.message)}</p>`;$('[data-close]').onclick=closeModal;}}
function renderMedicalRecord(record){const profile=record.profile;modal.innerHTML=`<div class="modal-head"><h2>ملف ${escapeHtml(profile.name)}</h2><button class="close" data-close>×</button></div><div class="doctor-meta"><span class="tag">رقم الملف: ${escapeHtml(record.patientId)}</span><span class="tag">البريد: ${escapeHtml(current.email)}</span></div><div style="margin:16px 0"><h3 style="margin:0 0 8px;font-size:16px">السجل الطبي والمواعيد</h3><p style="font-size:12px;color:#53666c">وضع القراءة فقط. تُضاف الحجوزات والمتابعات وتقارير التحاليل والأشعة إلى الملف بواسطة فريق الرعاية.</p></div><div id="recordList">${record.records.length?record.records.map(recordCard).join(''):'<p style="text-align:center;color:#71838b;padding:20px">لا توجد سجلات أو مواعيد بعد.</p>'}</div>`;
  $('[data-close]').onclick=closeModal;document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadRecord(b.dataset.download));}
function openEntryForm(){modal.innerHTML=`<div class="modal-head"><h2>إضافة سجل إلى ملفك</h2><button class="close" data-close>×</button></div><form id="entryForm"><div class="form-row"><label>نوع السجل</label><select name="category"><option value="visit">زيارة طبية</option><option value="diagnosis">تشخيص</option><option value="treatment">علاج</option><option value="medication">دواء</option><option value="surgery">عملية أو إجراء</option><option value="allergy">حساسية</option></select></div><div class="form-row"><label>العنوان</label><input name="title" required minlength="2" maxlength="160" placeholder="أدخل اسم السجل"></div><div class="form-row"><label>التاريخ (اختياري)</label><input name="serviceDate" type="date"></div><div class="form-row"><label>التفاصيل</label><textarea name="detail" required minlength="2" maxlength="5000" rows="4" style="width:100%;padding:11px;border:1px solid #dae5e6;border-radius:10px"></textarea></div><p style="font-size:11px;color:#80653b">سيُوسم السجل بأنه مُدخل من المريض وبانتظار مراجعة سريرية.</p><p id="entryError" style="color:#ad4848;font-size:12px"></p><button class="btn" style="width:100%">حفظ السجل</button></form>`;$('[data-close]').onclick=()=>openMedicalRecord();$('#entryForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{await api('/api/record-entry',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))});toast('تمت إضافة السجل إلى ملفك.');renderMedicalRecord(await api('/api/medical-record'));}catch(error){$('#entryError').textContent=error.message;button.disabled=false;}};}
function openUploadForm(){modal.innerHTML=`<div class="modal-head"><h2>رفع نتيجة إلى ملفك الطبي</h2><button class="close" data-close>×</button></div><form id="uploadForm"><div class="form-row"><label>نوع النتيجة</label><select name="category"><option value="lab">تحليل</option><option value="imaging">أشعة</option></select></div><div class="form-row"><label>اسم التحليل أو الأشعة</label><input name="title" required minlength="2" placeholder="مثل: صورة دم كاملة"></div><div class="form-row"><label>الملف (PDF أو JPG أو PNG أو DICOM، حد ١٥ ميجابايت)</label><input name="file" type="file" accept="application/pdf,image/jpeg,image/png,application/dicom,.dcm" required></div><div class="form-row"><label>ملاحظة اختيارية</label><input name="note" maxlength="1000" placeholder="تاريخ الفحص أو اسم المركز"></div><p id="uploadError" style="color:#ad4848;font-size:12px"></p><button class="btn" style="width:100%">رفع وإضافة إلى الملف الطبي</button></form>`;$('[data-close]').onclick=()=>openMedicalRecord();$('#uploadForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;button.textContent='جارٍ رفع الملف…';try{await api('/api/upload',{method:'POST',body:new FormData(e.currentTarget)});toast('تم رفع النتيجة وإضافتها إلى ملفك.');const record=await api('/api/medical-record');renderMedicalRecord(record);}catch(error){$('#uploadError').textContent=error.message;button.disabled=false;button.textContent='إعادة المحاولة';}};}
async function downloadRecord(id){try{const response=await fetch(`/api/medical-record/${encodeURIComponent(id)}/file`,{credentials:'same-origin'});if(!response.ok)throw new Error('تعذر تنزيل الملف.');const blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`نتيجة-${id}`;a.click();URL.revokeObjectURL(a.href);}catch(e){toast(e.message);}}
$('#myBookings').onclick=()=>current?.role==='patient'?openAppointments():location.assign('/login');$('#openPatient').onclick=openRecordGate;$('#searchCta').onclick=()=>{$('#searchName').focus();window.scrollTo({top:0,behavior:'smooth'});};$('#searchBtn').onclick=filterDoctors;$('#searchName').addEventListener('keydown',e=>{if(e.key==='Enter')filterDoctors();});$('#clearFilters').onclick=()=>{$('#searchName').value='';$('#searchCity').value='';$('#doctorsTitle').textContent='الأطباء';renderDoctors([]);};$('#allSpecialties').onclick=()=>{window.showAllSpecs=!window.showAllSpecs;$('#allSpecialties').textContent=window.showAllSpecs?'عرض أقل ↑':'عرض كل التخصصات ←';showSpecs();};
document.querySelectorAll('[data-care="clinic"]').forEach(button=>button.onclick=()=>{$('#searchName').focus();document.querySelectorAll('[data-care]').forEach(item=>item.classList.remove('active'));button.classList.add('active');window.scrollTo({top:0,behavior:'smooth'});});document.querySelectorAll('[data-service-request]').forEach(button=>button.onclick=()=>openServiceRequest(button.dataset.serviceRequest));
renderBranches();showSpecs();renderDoctors([]);refreshCurrent().then(()=>{if(!current)return;if(current.mustChangePassword){forcePasswordChange();return;}const panel=new URLSearchParams(location.search).get('panel');if(panel==='admin'&&current.role==='admin')openAdminPanel();else if(panel==='branch'&&['branch_manager','branch_staff'].includes(current.role))openBranchPanel();else if(panel==='doctor'&&current.role==='doctor')openDoctorPanel();if(['admin','branch','doctor'].includes(panel))history.replaceState({},'', '/');}).catch(()=>{});
